378	/** Returns a safe http/https URL or null. */
379	function safeUrl(url) {
380	  if (!url || typeof url !== 'string') return null;
381	  return (url.startsWith('http://') || url.startsWith('https://')) ? url : null;
382	}
383	
384	/** Returns a short human-readable label for a URL (hostname only). */
385	function urlLabel(url) {
386	  try {
387	    const hostname = new URL(url).hostname.replace(/^www\./, '');
388	    return hostname + ' \u2197'; // ↗ external-link symbol
389	  } catch {
390	    return url.length > 50 ? url.slice(0, 50) + '\u2026' : url;
391	  }
392	}
