394	function buildSpecialistDetail(payload) {
395	  const pct = payload.confidence !== undefined ? Math.round(payload.confidence * 100) : 0;
396	  const confColor = pct >= 70 ? 'var(--success)' : pct >= 40 ? 'var(--warning)' : 'var(--danger)';
397	
398	  let html = '';
399	
400	  // Confidence
401	  html += `<div class="step-dl-row">
402	    <span class="step-dl-label">Confidence</span>
403	    <div class="step-conf-bar"><div class="step-conf-fill" style="width:${pct}%;background:${confColor}"></div></div>
404	    <span class="step-conf-pct" style="color:${confColor}">${pct}%</span>
405	  </div>`;
406	
407	  // Claims
408	  if (payload.claims && payload.claims.length > 0) {
409	    html += `<div class="step-dl-label">Key Claims</div><ul class="step-claims">`;
410	    payload.claims.forEach(c => { html += `<li>${escapeHtml(c)}</li>`; });
411	    html += `</ul>`;
412	  }
413	
414	  // Evidence
415	  if (payload.evidence && payload.evidence.length > 0) {
416	    html += `<div class="step-dl-label">Evidence &amp; Sources</div>`;
417	    payload.evidence.forEach(ev => {
418	      const link = safeUrl(ev.source_url);
419	      const filingId = ev.filing_identifier;
420	      html += `<div class="step-evidence-item">
421	        <span class="step-source-badge">${escapeHtml(ev.source_type || '')}</span>
422	        <span class="step-evidence-text">${escapeHtml((ev.text || '').slice(0, 220))}${(ev.text || '').length > 220 ? '…' : ''}</span>
423	        ${link ? `<div><a class="step-source-link" href="${escapeHtml(link)}" target="_blank" rel="noopener noreferrer">${escapeHtml(urlLabel(link))}</a></div>` : ''}
424	        ${!link && filingId ? `<div class="step-filing-id">${escapeHtml(filingId)}</div>` : ''}
425	      </div>`;
426	    });
427	  }
428	
429	  // Failure reason
430	  if (!payload.success && payload.failure_reason) {
431	    html += `<div class="step-failure"><span class="step-dl-label">Failure Reason</span> ${escapeHtml(payload.failure_reason)}</div>`;
432	  }
433	
434	  // Tool Calls
435	  if (payload.tool_history && payload.tool_history.length > 0) {
436	    html += `<div class="step-dl-label">Tool Calls (${payload.tool_history.length})</div>`;
437	    payload.tool_history.forEach(entry => {
438	      const toolName = entry.name || 'unknown';
439	      const isExecPy = toolName === 'execute_python';
440	      html += `<div class="step-tool-call-item">`;
441	      html += `<div class="step-tool-call-header">`;
442	      html += `<span class="step-source-badge">${escapeHtml(toolName)}</span>`;
443	      if (!isExecPy && entry.args) {
444	        const argStr = JSON.stringify(entry.args);
445	        html += `<span class="step-tool-args">${escapeHtml(argStr.length > 120 ? argStr.slice(0, 120) + '\u2026' : argStr)}</span>`;
446	      }
447	      html += `</div>`;
448	      if (isExecPy && entry.args && entry.args.code) {
449	        html += `<pre class="step-code-block"><code>${escapeHtml(entry.args.code)}</code></pre>`;
450	        const result = entry.result;
451	        const stdout = result && (result.stdout || (result.data && result.data.stdout));
452	        const stderr = result && (result.error || (result.data && result.data.error));
453	        if (stdout) {
454	          html += `<pre class="step-code-output">${escapeHtml(stdout.slice(0, 600))}${stdout.length > 600 ? '\n\u2026' : ''}</pre>`;
455	        }
456	        if (stderr) {
457	          html += `<div class="step-tool-error">${escapeHtml(stderr.slice(0, 300))}</div>`;
458	        }
459	      }
460	      html += `</div>`;
461	    });
462	  }
463	
464	  return html;
465	}
